// Builds a local git repo whose history tells an infrastructure story, generated by our own compiler.
//   npx tsx scripts/make-demo-repo.ts /tmp/cloud-canvas-demo
import { execFileSync } from 'node:child_process';
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { TEMPLATES, compile, subnetId, subnetNodes, vpcSize } from '../src';
import type { Graph } from '../src';

const dest = process.argv[2] ?? '/tmp/cloud-canvas-demo';
const NAME = process.env.GIT_AUTHOR_NAME ?? 'Platform Engineer';
const EMAIL = process.env.GIT_AUTHOR_EMAIL ?? 'platform@example.com';
const g = (cmd: string[], env: Record<string, string> = {}) => execFileSync('git', ['-C', dest, ...cmd], { encoding: 'utf8', env: { ...process.env, ...env } });

rmSync(dest, { recursive: true, force: true });
mkdirSync(dest, { recursive: true });
g(['init', '-q', '-b', 'main']);
g(['config', 'user.name', NAME]);
g(['config', 'user.email', EMAIL]);

const base = TEMPLATES.find((t) => t.id === 'ecs-cluster')!.build({ name: 'member-portal', squad: 'digital-services', environment: 'dev', region: 'ap-southeast-1' });
// start smaller: service + ALB + DB, no queue
let graph: Graph = structuredClone(base);
graph.nodes = graph.nodes.filter((n) => n.id !== 'q');
graph.edges = graph.edges.filter((e) => e.target !== 'q');

let day = 0;
function commit(message: string, mutate: (x: Graph) => void, who = NAME) {
  mutate(graph);
  const r = compile(graph);
  if (!r.ok) throw new Error(`${message}: ${r.diagnostics.filter((d) => d.severity === 'error').map((d) => d.message).join('; ')}`);
  const dir = join(dest, 'infra/dev');
  mkdirSync(dir, { recursive: true });
  for (const f of r.files) writeFileSync(join(dir, f.path === 'azure-pipelines.yml' ? '../azure-pipelines.yml' : f.path), f.content);
  const when = new Date(Date.UTC(2026, 10, 2 + day++, 9, 30)).toISOString();
  g(['add', '-A']);
  g(['commit', '-q', '-m', message, `--author=${who} <${EMAIL}>`], { GIT_AUTHOR_DATE: when, GIT_COMMITTER_DATE: when });
}
const node = (x: Graph, id: string) => x.nodes.find((n) => n.id === id)!;

writeFileSync(join(dest, 'README.md'), '# member-portal infrastructure\n\nTerraform for the member portal, generated and reviewed with Cloud Canvas.\n');
g(['add', '-A']);
g(['commit', '-q', '-m', 'Add README'], { GIT_AUTHOR_DATE: '2026-11-01T09:00:00Z', GIT_COMMITTER_DATE: '2026-11-01T09:00:00Z' });

commit('Initial infrastructure: ALB, ECS service and Postgres in a VPC', () => {});
commit('Add jobs queue for background work', (x) => {
  x.nodes.push({ id: 'q', type: 'aws.sqs', position: { x: 900, y: 238 }, properties: { name: 'jobs', fifo: false, visibility: 30, dlq: true } });
  x.edges.push({ id: 'svc-q', source: 'svc', target: 'q' });
}, 'Priya Nair');
commit('Add audit log bucket for the service', (x) => {
  x.nodes.push({ id: 'audit', type: 'aws.s3', position: { x: 900, y: 400 }, properties: { name: 'audit', versioning: true, forceDestroy: false } });
  x.edges.push({ id: 'svc-audit', source: 'svc', target: 'audit' });
}, 'Priya Nair');
commit('Scale the API: 1 vCPU, 2 GB and 4 tasks', (x) => { Object.assign(node(x, 'svc').properties, { cpu: 1024, memory: 2048, desiredCount: 4 }); });
commit('Terminate TLS on the ALB with an ACM certificate', (x) => {
  node(x, 'alb').properties.https = true;
  x.nodes.push({ id: 'cert', type: 'aws.acm', position: { x: 900, y: 560 }, properties: { name: 'cert', domainName: 'portal.example.gov.sg', hostedZone: '' } });
  x.edges.push({ id: 'cert-alb', source: 'cert', target: 'alb' });
}, 'Wei Jie Tan');
commit('Cost saving: drop Multi-AZ on the database and shrink the instance', (x) => { Object.assign(node(x, 'db').properties, { multiAz: false, instanceClass: 'db.t4g.micro' }); }, 'Wei Jie Tan');
commit('Add a third availability zone to the network', (x) => {
  const v = node(x, 'vpc1');
  v.size = vpcSize(3);
  x.nodes.push(...subnetNodes('vpc1', String(v.properties.cidr), 3).filter((n) => n.properties.az === 'c'));
});
commit('Make the load balancer internal; the portal now sits behind the corporate gateway', (x) => {
  const alb = node(x, 'alb');
  alb.properties.internal = true;
  alb.parentId = subnetId('vpc1', 'private', 'a');
  alb.position = { x: 120, y: 38 };
});
commit('Move the database to the larger instance again and turn Multi-AZ back on', (x) => { Object.assign(node(x, 'db').properties, { multiAz: true, instanceClass: 'db.t4g.medium' }); }, 'Priya Nair');

commit('Retire the jobs queue: background work moves to the shared platform service', (x) => {
  x.nodes = x.nodes.filter((n) => n.id !== 'q');
  x.edges = x.edges.filter((e) => e.target !== 'q');
}, 'Wei Jie Tan');

console.log(g(['log', '--format=%h  %an  %s']));
